import json, math, sys
firstError = secondError = coordinatesJson = ""
if bool(sys.argv[1]) != bool(sys.argv[2]):
    firstError = "Latitude and Longitude must either both be supplied or both be empty."
elif sys.argv[1] and sys.argv[2]:
    try:
        latitude, longitude = float(sys.argv[1]), float(sys.argv[2])
    except ValueError:
        firstError = "Latitude and Longitude must be decimal numbers."
    else:
        if not math.isfinite(latitude) or not math.isfinite(longitude):
            firstError = "Latitude and Longitude must be finite decimal numbers."
        else:
            if latitude < -90 or latitude > 90:
                firstError = "Latitude must be between -90 and 90."
            if longitude < -180 or longitude > 180:
                secondError = "Longitude must be between -180 and 180."
            if not firstError and not secondError:
                coordinatesJson = json.dumps({"ClassId":"comm.GeoPoint","ObjectType":"comm.GeoPoint","Latitude":latitude,"Longitude":longitude},separators=(",",":"),allow_nan=False)
